def score(program: str) -> float:
    n = max(len(program), 1)
    letters = [c for c in program if c.isalpha()]
    v = sum(c in "aeiou" for c in letters) / max(len(letters), 1)
    p = sum(not c.isalnum() and not c.isspace() for c in program) / n
    return min(1.0, v * 0.6 + p * 1.5)

def score(program: str) -> float:
    try:
        import ast
        x = len(list(ast.walk(ast.parse(program))))
        return 1.0 - x / 200.0
    except:
        return 0.0

